fn string_xor(a: Vec<char>, b: Vec<char>) -> Vec<char> {
    a.into_iter()
        .zip(b.into_iter())
        .map(|(x, y)| if x == y { '0' } else { '1' })
        .collect()
}

// Example usage and simple tests
fn main() {
    let a: Vec<char> = "11001".chars().collect();
    let b: Vec<char> = "10111".chars().collect();
    let result = string_xor(a, b);
    let result_str: String = result.into_iter().collect();
    assert_eq!(result_str, "01110");
    println!("XOR result: {}", result_str);

    // Empty input
    let empty1: Vec<char> = Vec::new();
    let empty2: Vec<char> = Vec::new();
    let result_empty = string_xor(empty1, empty2);
    assert!(result_empty.is_empty());
    println!("Empty XOR result: {:?}", result_empty);
}